<p class="eyebrow">Inventory</p><h1>수량 확인</h1><p class="muted">판매 가능 재고는 주문 시 차감하고, 미결제 취소·출고 전 전액 환불·재판매 가능한 반품 시 되돌립니다. 교환 회수와 재출고는 각각 기록합니다.</p>
<section class="panel table-wrap"><h2>옵션별 판매 가능 재고</h2><table><thead><tr><th>상품 / 옵션</th><th>상태</th><th class="num">가격</th><th class="num">판매 가능</th><th class="num">주문 확보</th><th class="num">출고 전 보유</th><th></th></tr></thead><tbody><?php foreach ($inventory as $row): ?><tr><td><?= $this->e($row['name']) ?><br><small><?= $this->e(implode(' / ', array_filter([$row['option1'], $row['option2']]))) ?></small></td><td><?= $row['active'] ? '사용' : '미사용' ?></td><td class="num"><?= number_format((int) $row['price']) ?>원</td><td class="num"><?= number_format((int) $row['stock']) ?>개</td><td class="num"><?= number_format((int) $row['reserved']) ?>개</td><td class="num"><?= number_format((int) $row['stock'] + (int) $row['reserved']) ?>개</td><td><a href="<?= $this->e($url) ?>/products?id=<?= $this->e($row['product_id']) ?>">재고 조정</a></td></tr><?php endforeach ?></tbody></table><nav class="pagination"><?php if ($page_number > 1): ?><a href="<?= $this->e($url) ?>/inventory?p=<?= $page_number - 1 ?>">이전</a><?php endif ?><?php if (count($inventory) === 100): ?><a href="<?= $this->e($url) ?>/inventory?p=<?= $page_number + 1 ?>">다음</a><?php endif ?></nav></section>
<section class="panel table-wrap"><h2>최근 수량 변동 100건</h2><table><thead><tr><th>일시</th><th>상품 / 옵션</th><th>사유</th><th class="num">변동</th><th>관련 번호</th></tr></thead><tbody><?php $stockLabels = ['initial' => '초기 입고', 'adjustment' => '운영자 조정', 'order' => '주문 확보', 'cancel' => '주문 취소', 'return' => '반품 입고', 'exchange_return' => '교환 회수', 'exchange_ship' => '교환 출고']; foreach ($stock_events as $row): ?><tr><td><?= $this->e($time($row['created_at'])) ?></td><td><?= $this->e($row['name']) ?><br><small><?= $this->e($row['option1'] . ' ' . $row['option2']) ?></small></td><td><?= $this->e($stockLabels[$row['kind']] ?? $row['kind']) ?></td><td class="num"><?= (int) $row['delta'] > 0 ? '+' : '' ?><?= (int) $row['delta'] ?></td><td class="order-id"><?= $this->e($row['reference']) ?></td></tr><?php endforeach ?></tbody></table></section>
